import { ExternalLink, Heart, ServerCog } from "lucide-react";
import { Link } from "react-router-dom";
import { appGlyph, formatDate } from "../../lib/utils";
import type { StoreApp } from "../../types";
import { AppIcon, Badge, Button } from "../../components/ui";
import { useFavorites } from "./favorites";
import { AppAdminLink, useCanManageApps } from "./admin-shortcut";
import { AppStatusBadge } from "./app-status";
import { SecurityVerifiedBadge } from "../security-check/verified-badge";

// The public detail route serves only published, public apps (see
// GetAppBySlug with includeAll=false), so this is what decides whether a card
// may link to /apps/{slug} at all.
function publiclyViewable(app: StoreApp) {
  return app.status === "published" && app.visibility !== "private";
}

// The public catalog only ever lists published apps, so the status is noise
// there; an owner's own list mixes drafts, pending, rejected and archived apps
// and needs it to tell them apart. Those apps have no public page either, so
// in that list the card opens the owner's edit screen instead of a 404.
export function AppCard({
  app,
  showStatus = false,
}: {
  app: StoreApp;
  showStatus?: boolean;
}) {
  const { isFavorite, toggle } = useFavorites();
  const favorite = isFavorite(app.slug);
  const canManage = useCanManageApps();
  const viewable = !showStatus || publiclyViewable(app);
  const target = viewable
    ? `/apps/${encodeURIComponent(app.slug)}`
    : `/my/apps/${encodeURIComponent(app.id)}/edit`;
  return (
    <article className="card app-card">
      <div className="app-card-body">
        <div className="app-card-head">
          <AppIcon app={app} />
          <div className="min-w-0">
            <h2 className="app-card-name">
              {/* The link stretches over the whole card (see .app-card-name a
                  in styles.css), so the summary and the badges open the app
                  too — only the footer controls stay on top of it. */}
              <Link
                to={target}
                title={viewable ? undefined : `${app.name} 수정 화면 열기`}
              >
                {app.name}
              </Link>
            </h2>
            <p className="app-card-summary">{app.summary}</p>
          </div>
        </div>
        <div className="badge-row" aria-label="앱 특성">
          {showStatus && <AppStatusBadge status={app.status} />}
          <SecurityVerifiedBadge app={app} />
          {(app.category?.name || app.categoryName) && (
            <Badge>{app.category?.name || app.categoryName}</Badge>
          )}
          {app.language && <Badge>{app.language}</Badge>}
          {app.supportsMcp && (
            <Badge tone="primary">
              <ServerCog size={14} /> MCP
            </Badge>
          )}
          {app.supportsApi && <Badge tone="positive">API</Badge>}
        </div>
      </div>
      <footer className="app-card-footer">
        <span className="text-[13px] text-[var(--text-muted)]">
          {app.updatedAt
            ? `${formatDate(app.updatedAt)} 업데이트`
            : app.version
              ? `v${app.version.replace(/^v/, "")}`
              : "앱 정보 보기"}
        </span>
        <div className="top-actions">
          <Button
            variant="ghost"
            size="sm"
            aria-label={`${app.name} ${favorite ? "즐겨찾기 해제" : "즐겨찾기 추가"}`}
            aria-pressed={favorite}
            onClick={() => toggle(app.slug)}
          >
            <Heart size={17} fill={favorite ? "currentColor" : "none"} />
          </Button>
          {canManage && (
            <AppAdminLink appId={app.id} appName={app.name} compact />
          )}
          {/* An administrator's card already carries the admin shortcut next
              to the favourite button; spelling out 자세히 as well crowds the
              footer, so their row is icons only. An unpublished app has no
              detail page to show, so its card has no 자세히 at all. */}
          {viewable && (
            <Link
              className={`button button-secondary button-sm${canManage ? " button-icon" : ""}`}
              to={target}
              title={`${app.name} 상세 보기`}
              aria-label={`${app.name} 상세 보기`}
            >
              {!canManage && <span>자세히</span>}
              <ExternalLink size={15} aria-hidden="true" />
            </Link>
          )}
        </div>
      </footer>
    </article>
  );
}

export function AppAvatar({ name, icon }: { name: string; icon?: string }) {
  return (
    <span className="app-icon" aria-hidden="true">
      {appGlyph(name, icon)}
    </span>
  );
}
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { render, screen } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import { describe, expect, it, vi } from "vitest";
import { AuthProvider } from "../app/providers";
import { FavoritesProvider } from "../features/apps/favorites";
import { MyAppsPage } from "./personal-pages";

function myApp(overrides: Record<string, unknown>) {
  return {
    id: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
    slug: "agent-hub",
    name: "Agent Hub",
    summary: "AI 에이전트 카탈로그",
    ...overrides,
  };
}

function renderMyApps(items: Record<string, unknown>[]) {
  const fetchMock = vi.fn().mockImplementation(() =>
    Promise.resolve(
      new Response(JSON.stringify({ items, total: items.length }), {
        status: 200,
        headers: { "content-type": "application/json" },
      }),
    ),
  );
  vi.stubGlobal("fetch", fetchMock);
  const client = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  render(
    <QueryClientProvider client={client}>
      <MemoryRouter initialEntries={["/my/apps"]}>
        <AuthProvider>
          <FavoritesProvider>
            <MyAppsPage />
          </FavoritesProvider>
        </AuthProvider>
      </MemoryRouter>
    </QueryClientProvider>,
  );
}

describe("My applications", () => {
  it("labels each card with the status the owner cannot otherwise see", async () => {
    renderMyApps([
      myApp({ status: "draft" }),
      myApp({
        id: "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
        slug: "flow-studio",
        name: "Flow Studio",
        status: "pending_review",
      }),
      myApp({
        id: "cccccccc-cccc-4ccc-8ccc-cccccccccccc",
        slug: "secure-vault",
        name: "Secure Vault",
        status: "archived",
      }),
    ]);

    const cards = await screen.findAllByRole("article");
    expect(cards).toHaveLength(3);
    expect(cards[0]).toHaveTextContent("초안");
    expect(cards[1]).toHaveTextContent("검토 대기");
    expect(cards[2]).toHaveTextContent("보관됨");
    expect(screen.queryByRole("alert")).toBeNull();
  });

  it("opens the edit screen from a card the public detail route would 404 on", async () => {
    renderMyApps([
      myApp({ status: "published", visibility: "public" }),
      myApp({
        id: "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
        slug: "flow-studio",
        name: "Flow Studio",
        status: "pending_review",
      }),
      myApp({
        id: "cccccccc-cccc-4ccc-8ccc-cccccccccccc",
        slug: "secure-vault",
        name: "Secure Vault",
        status: "published",
        visibility: "private",
      }),
    ]);

    // A published, public app still opens its catalog page.
    const published = await screen.findByRole("heading", {
      name: "Agent Hub",
    });
    expect(published.querySelector("a")).toHaveAttribute(
      "href",
      "/apps/agent-hub",
    );
    expect(
      screen.getByRole("link", { name: "Agent Hub 상세 보기" }),
    ).toHaveAttribute("href", "/apps/agent-hub");

    // /apps/{slug} serves only published, public apps, so the other two have
    // no page there: the name link goes to the owner's edit screen and the
    // 자세히 button, with nothing to show, is left out.
    for (const [name, id] of [
      ["Flow Studio", "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"],
      ["Secure Vault", "cccccccc-cccc-4ccc-8ccc-cccccccccccc"],
    ]) {
      const heading = screen.getByRole("heading", { name });
      expect(heading.querySelector("a")).toHaveAttribute(
        "href",
        `/my/apps/${id}/edit`,
      );
      expect(
        screen.queryByRole("link", { name: `${name} 상세 보기` }),
      ).toBeNull();
    }
  });

  it("shows why a rejected app was sent back", async () => {
    renderMyApps([
      myApp({
        status: "rejected",
        review: {
          id: "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
          appId: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
          status: "rejected",
          level: 1,
          reason: "서비스 URL이 사내망에서 열리지 않습니다.",
          reviewerName: "검토자 김",
          decidedAt: "2026-09-01T08:00:00Z",
        },
      }),
    ]);

    const notice = await screen.findByRole("alert");
    expect(notice).toHaveTextContent(
      "서비스 URL이 사내망에서 열리지 않습니다.",
    );
    expect(notice).toHaveTextContent("검토자 김");
    expect(notice).toHaveTextContent("1단계 검토");
  });

  it("keeps a superseded reason hidden once the app is back in review", async () => {
    renderMyApps([
      myApp({
        status: "pending_review",
        review: {
          id: "cccccccc-cccc-4ccc-8ccc-cccccccccccc",
          appId: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
          status: "pending",
          level: 1,
        },
      }),
    ]);

    expect(
      await screen.findByRole("heading", { name: "Agent Hub" }),
    ).toBeVisible();
    expect(screen.queryByRole("alert")).toBeNull();
  });
});

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import { afterEach, describe, expect, it, vi } from "vitest";
import { AuthProvider } from "../app/providers";
import { FavoritesProvider } from "../features/apps/favorites";
import { AppDetailPage, AppsPage } from "./public-pages";

describe("Apps route state", () => {
  it("restores search, category and sort controls from the URL", async () => {
    const fetchMock = vi.fn().mockImplementation((input: RequestInfo | URL) => {
      const url = String(input);
      const payload = url.includes("/categories")
        ? [{ id: "ai", slug: "ai", name: "AI" }]
        : {
            items: [
              {
                id: "1",
                slug: "agent-hub",
                name: "Agent Hub",
                summary: "AI 에이전트 카탈로그",
                category: { id: "ai", slug: "ai", name: "AI" },
                status: "published",
              },
            ],
            total: 1,
            limit: 24,
            offset: 0,
          };
      return Promise.resolve(
        new Response(JSON.stringify(payload), {
          status: 200,
          headers: { "content-type": "application/json" },
        }),
      );
    });
    vi.stubGlobal("fetch", fetchMock);
    const client = new QueryClient({
      defaultOptions: { queries: { retry: false } },
    });

    render(
      <QueryClientProvider client={client}>
        <MemoryRouter
          initialEntries={["/apps?q=agent&category=ai&sort=trending"]}
        >
          <AuthProvider>
            <FavoritesProvider>
              <AppsPage />
            </FavoritesProvider>
          </AuthProvider>
        </MemoryRouter>
      </QueryClientProvider>,
    );

    expect(screen.getByLabelText("앱 검색")).toHaveValue("agent");
    expect(screen.getByLabelText("정렬")).toHaveValue("trending");
    await waitFor(() =>
      expect(screen.getByLabelText("카테고리")).toHaveValue("ai"),
    );
    expect(
      await screen.findByRole("heading", { name: "Agent Hub" }),
    ).toBeVisible();
    // Everything in the public catalog is published; only an owner's own
    // list labels cards with their status.
    expect(screen.queryByText("게시됨")).toBeNull();
    expect(
      fetchMock.mock.calls.some(([url]) => String(url).includes("q=agent")),
    ).toBe(true);
  });
});

describe("App detail introduction", () => {
  // jsdom reports 0 for both heights, which is also what it reports after
  // these stubs are put back, so the reset is the plain jsdom answer.
  const stubHeight = (name: "scrollHeight" | "clientHeight", value: number) =>
    Object.defineProperty(HTMLElement.prototype, name, {
      configurable: true,
      get: () => value,
    });
  afterEach(() => {
    stubHeight("scrollHeight", 0);
    stubHeight("clientHeight", 0);
  });

  const renderDetail = (description: string) => {
    vi.stubGlobal(
      "fetch",
      vi.fn().mockImplementation((input: RequestInfo | URL) => {
        const url = String(input);
        const payload = url.includes("/documents")
          ? { items: [] }
          : url.includes("/apps/agent-hub")
            ? {
                id: "1",
                slug: "agent-hub",
                name: "Agent Hub",
                summary: "AI 에이전트 카탈로그",
                description,
                status: "published",
              }
            : {};
        return Promise.resolve(
          new Response(JSON.stringify(payload), {
            status: 200,
            headers: { "content-type": "application/json" },
          }),
        );
      }),
    );
    const client = new QueryClient({
      defaultOptions: { queries: { retry: false } },
    });
    render(
      <QueryClientProvider client={client}>
        <MemoryRouter initialEntries={["/apps/agent-hub"]}>
          <AuthProvider>
            <FavoritesProvider>
              <Routes>
                <Route path="/apps/:slug" element={<AppDetailPage />} />
              </Routes>
            </FavoritesProvider>
          </AuthProvider>
        </MemoryRouter>
      </QueryClientProvider>,
    );
  };

  it("folds a long description away so what follows it stays on screen", async () => {
    // jsdom lays nothing out, so the overflow the clamp would produce in a
    // browser is stated here.
    stubHeight("scrollHeight", 600);
    stubHeight("clientHeight", 200);
    renderDetail("긴 소개 ".repeat(200));
    const intro = await screen.findByText(/긴 소개/);
    expect(intro).toHaveClass("is-clamped");

    await userEvent.click(screen.getByRole("button", { name: /더 보기/ }));
    expect(intro).not.toHaveClass("is-clamped");
    expect(screen.getByRole("button", { name: /접기/ })).toHaveAttribute(
      "aria-expanded",
      "true",
    );
  });

  it("leaves a short description alone", async () => {
    stubHeight("scrollHeight", 120);
    stubHeight("clientHeight", 200);
    renderDetail("한 줄짜리 소개");
    expect(await screen.findByText("한 줄짜리 소개")).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: /더 보기/ })).toBeNull();
  });
});
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { render, screen } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import { describe, expect, it, vi } from "vitest";
import { AuthProvider } from "../../app/providers";
import { FavoritesProvider } from "./favorites";
import { AppCard } from "./app-card";
import type { StoreApp } from "../../types";

const app: StoreApp = {
  id: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
  slug: "agent-hub",
  name: "Agent Hub",
  summary: "팀의 AI Agent를 발견하고 실행하는 통합 허브",
  status: "published",
};

function renderCard(roles: string[]) {
  vi.stubGlobal(
    "fetch",
    vi.fn().mockImplementation((input: RequestInfo | URL) => {
      const url = String(input);
      const payload = url.includes("/auth/session")
        ? { authenticated: !!roles.length, user: { roles } }
        : {};
      return Promise.resolve(
        new Response(JSON.stringify(payload), {
          status: 200,
          headers: { "content-type": "application/json" },
        }),
      );
    }),
  );
  const client = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  render(
    <QueryClientProvider client={client}>
      <MemoryRouter>
        <AuthProvider>
          <FavoritesProvider>
            <AppCard app={app} />
          </FavoritesProvider>
        </AuthProvider>
      </MemoryRouter>
    </QueryClientProvider>,
  );
}

describe("App card", () => {
  it("spells out the detail link for a visitor", async () => {
    renderCard([]);
    expect(
      await screen.findByRole("link", { name: "Agent Hub 상세 보기" }),
    ).toHaveTextContent("자세히");
    expect(
      screen.queryByRole("link", { name: "Agent Hub 관리 설정 열기" }),
    ).toBeNull();
  });

  it("reduces the detail link to an icon for an administrator", async () => {
    renderCard(["user", "admin"]);
    // An administrator's footer also carries the admin shortcut, so the detail
    // link drops its wording and keeps only the icon.
    expect(
      await screen.findByRole("link", { name: "Agent Hub 관리 설정 열기" }),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("link", { name: "Agent Hub 상세 보기" }).textContent,
    ).toBe("");
  });

  it("points the whole card at the app through the name link", () => {
    renderCard([]);
    const name = screen.getByRole("heading", { name: "Agent Hub" });
    const link = name.querySelector("a");
    // The overlay that makes the summary and the badges clickable is drawn
    // from this link in styles.css (.app-card-name a::after).
    expect(link).toHaveAttribute("href", "/apps/agent-hub");
    expect(link?.closest(".app-card")).not.toBeNull();
  });
});
import {
  createContext,
  useContext,
  useMemo,
  useState,
  type PropsWithChildren,
} from "react";
import { safeJsonParse } from "../../lib/utils";

const KEY = "appstore.favorites";
const FavoritesContext = createContext<{
  slugs: string[];
  isFavorite: (slug: string) => boolean;
  toggle: (slug: string) => void;
} | null>(null);

export function FavoritesProvider({ children }: PropsWithChildren) {
  const [slugs, setSlugs] = useState<string[]>(() =>
    safeJsonParse(localStorage.getItem(KEY), []),
  );
  const value = useMemo(
    () => ({
      slugs,
      isFavorite: (slug: string) => slugs.includes(slug),
      toggle: (slug: string) =>
        setSlugs((current) => {
          const next = current.includes(slug)
            ? current.filter((item) => item !== slug)
            : [...current, slug];
          localStorage.setItem(KEY, JSON.stringify(next));
          return next;
        }),
    }),
    [slugs],
  );
  return (
    <FavoritesContext.Provider value={value}>
      {children}
    </FavoritesContext.Provider>
  );
}

export function useFavorites() {
  const value = useContext(FavoritesContext);
  if (!value) throw new Error("FavoritesProvider가 필요합니다.");
  return value;
}
import { expect, test } from "@playwright/test";
import { installMockApi } from "./mock-api";

test("공개 탐색과 URL 검색 상태는 새로고침 후에도 유지된다", async ({
  page,
}) => {
  await installMockApi(page);
  await page.goto("/apps?q=agent&category=ai&sort=trending");
  await expect(page.getByRole("heading", { name: "모든 앱" })).toBeVisible();
  await expect(page.locator("#catalog-search")).toHaveValue("agent");
  await expect(page.getByLabel("카테고리")).toHaveValue("ai");
  await expect(page.getByLabel("정렬")).toHaveValue("trending");
  await expect(page.getByRole("heading", { name: "Agent Hub" })).toBeVisible();
  await page.reload();
  await expect(page).toHaveURL(/q=agent&category=ai&sort=trending/);
  await expect(page.locator("#catalog-search")).toHaveValue("agent");
});

test("비로그인 등록 접근은 원래 URL을 보존한 로그인 화면으로 이동한다", async ({
  page,
}) => {
  await installMockApi(page);
  await page.goto("/submit");
  await expect(page).toHaveURL(/\/login\?returnTo=%2Fsubmit/);
  await expect(
    page.getByRole("heading", { name: "AppStore 로그인" }),
  ).toBeVisible();
  await expect(page.getByText("AppStore v2.0.0")).toBeVisible();
});

